/**
 * Modal interruption of the page (`design/components/dialog.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dialog.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, useContext, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/dialog'
import { normalizeProps } from '@zag-js/solid'

import {
  BORROWED,
  IDENTITY,
  ResolvedSlot,
  afresh,
  agentMember,
  claimSlot,
  classes,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  modalFocusTarget,
  provide,
  resolveSlot,
  scope,
  useDirection,
  useMachine,
  useMediaQuery,
  type Defaults,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/dialog.module.css'
import Button from '../controls/Button'

export interface DialogProps {
  /**
   * Uses `alertdialog` rather than `dialog`, for an interruption the reader must answer.
   * ConfirmDialog sets it for its danger tone.
   */
  alert?: boolean
  children?: JSX.Element
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * Actions. One primary (`solid`), rightmost; dismiss is outline or ghost.
   */
  footer?: JSX.Element
  /**
   * Which footer control has focus on open; `dismiss` suits a panel that asks whether you meant
   * it (see `initialFocus`).
   */
  initialFocus?: 'primary' | 'dismiss'
  onOpenChange?: (open: boolean) => void
  open?: boolean
  /**
   * `'auto'` is the card, and the whole screen below `30rem` (the overlay class's viewport
   * exemption). `'sheet'` keeps the card above `30rem` and becomes a bottom sheet below it (the
   * sheet presentation, `design/components/README.md`). It is for content-light confirm and pick
   * dialogs, where a full-screen takeover is too heavy. Only the shape changes: scrim, trap,
   * `dismissible`, initial focus and return focus are Dialog's in both forms, which is why it
   * can be a prop.
   */
  presentation?: 'auto' | 'sheet'
  size?: 'sm' | 'md' | 'lg'
  title: string
  /**
   * A governed control, usually a Button, cloned to receive `onClick`, which also tells the
   * panel where it was opened from.
   */
  trigger?: JSX.Element
}

/** Modal interruption of the page. */
export default function Dialog(given: DialogProps): JSX.Element {
  const props = mergeProps(
    {
      closeLabel: 'Close',
      size: 'md',
      dismissible: true,
      initialFocus: 'primary',
      alert: false,
      presentation: 'auto',
    } as Defaults<
      DialogProps,
      'closeLabel' | 'size' | 'dismissible' | 'initialFocus' | 'alert' | 'presentation'
    >,
    claimSlot(given),
  )
  const lent = useContext(IDENTITY)
  const lender = useContext(BORROWED)
  return scope(() => {
    provide(BORROWED, undefined)
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const scrim = elementRef<HTMLElement>()
    const phone = useMediaQuery('phone')
    const triggerSlot = resolveSlot(
      () => props.trigger,
      () => ({ onClick: openFrom.value }),
    )
    const opener = createCell(null as HTMLElement | null)
    const sheet = createDerived(() => props.presentation === 'sheet' && phone())
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          role: props.alert ? 'alertdialog' : 'dialog',
          closeOnEscape: props.dismissible,
          closeOnInteractOutside: props.dismissible,
          initialFocusEl: () => modalFocusTarget(panel.value, props.initialFocus),
          finalFocusEl: () => opener.value,
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const openFrom = createDerived(() => (event?: Event) => {
      if (event?.currentTarget instanceof HTMLElement) opener.value = event.currentTarget
      api.value.setOpen(true)
    })
    const scrimPresent = usePresence(
      () => api.value.open,
      () => scrim.value,
      'dialog.scrim',
    )
    const panelPresent = usePresence(
      () => api.value.open,
      () => panel.value,
      () => (sheet.value ? 'sheet.panel' : 'dialog.panel'),
      { sheetSide: 'bottom' },
    )
    const effect1 = () => {
      void (lender && (lender.element = () => panel.value))
    }
    onMount(effect1)
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = lender
        ? () => {}
        : agentMember({
            member: 'Dialog',
            element: () => panel.value,
            state: () => ({ open: api.value.open }),
            actions: {
              close: () =>
                (() => {
                  if (!props.dismissible)
                    throw new Error('The dialog asks for a choice among its own actions.')
                  api.value.setOpen(false)
                })(),
            },
          })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <>
        {triggerSlot()}
        <Portal>
          {afresh(() => (
            <>
              {scrimPresent() ? (
                <div
                  {...mergeParts(api.value.getBackdropProps(), {
                    class: styles.scrim,
                    hidden: undefined,
                  })}
                  ref={scrim.attach}
                />
              ) : null}
              {panelPresent() ? (
                <ResolvedSlot of={() => props.footer}>
                  {(footerSlot) => (
                    <div
                      {...mergeParts(api.value.getPositionerProps(), {
                        class: classes(
                          sheet.value ? styles.sheetPositioner : undefined,
                          !sheet.value ? styles.positioner : undefined,
                        ),
                      })}
                    >
                      {/* panel */}
                      <div
                        {...mergeParts(api.value.getContentProps(), {
                          class: classes(
                            sheet.value ? styles.sheetPanel : undefined,
                            !sheet.value ? styles.panel : undefined,
                          ),
                          hidden: undefined,
                          'data-presentation': sheet.value ? 'sheet' : undefined,
                          'data-size': props.size,
                          'data-member': lent ?? 'dialog',
                        })}
                        ref={panel.attach}
                      >
                        {/* title */}
                        <h2 {...mergeParts(api.value.getTitleProps(), { class: styles.title })}>
                          {props.title}
                        </h2>
                        {props.description !== undefined ? (
                          <p
                            {...mergeParts(api.value.getDescriptionProps(), {
                              class: styles.description,
                            })}
                          >
                            {props.description}
                          </p>
                        ) : null}
                        {/* body */}
                        <div class={styles.body} data-dialog-part="body">
                          {props.children}
                        </div>
                        {footerSlot.filled() ? (
                          <div class={styles.footer} data-dialog-part="footer">
                            {footerSlot()}
                          </div>
                        ) : null}
                        {props.dismissible ? (
                          <div class={styles.close} data-dialog-part="close">
                            <Button
                              variant="ghost"
                              tone="neutral"
                              size="sm"
                              iconOnly={true}
                              icon="close"
                              label={props.closeLabel}
                              onClick={() => api.value.setOpen(false)}
                            />
                          </div>
                        ) : null}
                      </div>
                    </div>
                  )}
                </ResolvedSlot>
              ) : null}
            </>
          ))}
        </Portal>
      </>
    )
  })
}
